import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    # Count rounds, cooperation rates
    c_me = 0
    c_opp = 0
    for a in my:
        if a == 'C':
            c_me += 1
    for a in opp:
        if a == 'C':
            c_opp += 1

    # Track opponent behavior patterns
    opp_defections = 0
    last_opp = opp[-1]
    recent_opp = opp[-10:] if n >= 10 else opp

    # Detect persistent defectors early
    if n >= 6:
        recent_def_count = sum(1 for a in recent_opp if a == 'D')
        if recent_def_count >= 5 and c_opp < n * 0.4:
            # Mostly defecting: defect to limit losses, but occasionally test
            if rng.random() < 0.05:
                return 'C'
            return 'D'

    # Start cooperative but responsive
    # If opponent has been very cooperative, stay cooperative
    if n >= 3:
        opp_coop_rate = c_opp / n
    else:
        opp_coop_rate = 1.0

    # Tit-for-tat with some forgiveness early game
    if n <= 3:
        return 'C'

    # If opponent just defected
    if last_opp == 'D':
        # Count consecutive opponent defections at end
        consec_def = 0
        for a in reversed(opp):
            if a == 'D':
                consec_def += 1
            else:
                break

        if consec_def == 1:
            # Single defection: retaliate once then forgive
            if my[-1] == 'D':
                # We already retaliated, go back to C
                return 'C'
            return 'D'
        elif consec_def == 2:
            # Two in a row: retaliate but with a chance to probe
            if my[-1] == 'D' and my[-2] == 'D':
                return 'C'
            return 'D'
        else:
            # Persistent defection: defect more, but occasionally probe
            if rng.random() < 0.1:
                return 'C'
            return 'D'

    # Opponent cooperated
    if last_opp == 'C':
        # If we defected last turn as retaliation and opponent still cooperated,
        # reward them with cooperation
        if my[-1] == 'D' and n >= 2:
            # Opponent forgave our defection: cooperate to restore
            return 'C'
        return 'C'

    return 'C'

